(()=>{'use strict';const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let events=[],contracts=[],limit=40;
const anchor=(r)=>`<a href="${esc(r.url)}">${esc(r.label)}</a>`;
const table=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
function options(id,values){for(const v of [...new Set(values)].sort()){$(id).add(new Option(v,v));}}
function getMatches(){let q=$('search').value.trim().toLowerCase();let exact=events.some(e=>e.id.toLowerCase()===q);return events.filter(e=>($('view').value==='all'||e.featured)&&(!$('layer').value||e.layer===$('layer').value)&&(!$('kind').value||e.kind===$('kind').value)&&(!$('year').value||e.date.startsWith($('year').value))&&(!q||(exact?e.id.toLowerCase()===q:e.search.includes(q)))).sort((a,b)=>{if(!a.date||!b.date)return Number(!a.date)-Number(!b.date)||a.id.localeCompare(b.id);return $('order').value==='asc'?a.date.localeCompare(b.date)||a.id.localeCompare(b.id):b.date.localeCompare(a.date)||a.id.localeCompare(b.id);});}
const dollars=x=>'$'+Number(x).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
function values(e){if(!e.valuations?.length)return '';let rows=e.valuations;return `<div class="values"><b>USD at the relevant time</b>${rows.slice(0,5).map(v=>`<p><strong>${v.usd!==undefined?esc(dollars(v.usd)):'Unpriced'}</strong> · ${esc(Number(v.amount).toLocaleString('en-US',{maximumFractionDigits:6}))} ${esc(v.asset)}<small>${esc(v.basis)} · ${esc(v.at_utc?.slice(0,10)||'date not established')}${v.status==='unpriced'?' · '+esc(v.reason||'No reliable historical value established'):''}</small></p>`).join('')}${rows.length>5?`<p>${rows.length-5} further instruction amounts in the full details below.</p>`:''}</div>`;}
function card(e){let short=e.fact.length>800?e.fact.slice(0,800)+'…':e.fact;let ds=e.date?esc(e.date.slice(0,10)):'Undated public summary';let time=e.date.includes('T')?' · '+esc(e.date.slice(11,19))+' UTC':'';return `<article class="event" id="${esc(e.id)}"><div class="event-date">${ds}<span class="date-kind">${esc(e.date_kind)}${time}</span></div><div class="event-meta"><span class="tag">${esc(e.layer)} · ${esc(e.kind)}</span><a class="permalink" href="#event=${encodeURIComponent(e.id)}">Link to entry</a></div><h3>${esc(e.title)}</h3><p class="fact">${esc(short)}</p>${values(e)}${e.effect?`<p class="meaning"><b>Significance:</b> ${esc(e.effect)}</p>`:''}<p class="refs">${e.refs.map(anchor).join(' · ')}</p><details><summary>Read full text, votes or transaction details</summary>${e.fact.length>800?`<p class="fact">${esc(e.fact)}</p>`:''}<pre>${esc(JSON.stringify({...e.details,historical_values:e.valuations||[]},null,2))}</pre><p class="small">Record: ${esc(e.id)} · ${esc(e.status)}</p></details></article>`;}
function renderContext(rows){const box=$('record-context');if(!box)return;box.hidden=true;box.replaceChildren();if(rows.length!==1)return;const id=rows[0].id;const link=[...document.querySelectorAll('.chapter-sources a')].find(a=>a.hash==='#event='+encodeURIComponent(id)||a.hash==='#event='+id);const phase=link?.closest('.phase');if(!phase)return;box.innerHTML='<span>Discussed in the power-consolidation record</span><a href="#'+esc(phase.id)+'">'+esc(phase.querySelector('h2').textContent)+'</a>';box.hidden=false;const entry=$('events').querySelector('.event');if(entry){const origin=document.createElement('p');origin.className='entry-origin';origin.innerHTML='<a href="#'+esc(phase.id)+'">Back to power consolidation: '+esc(phase.querySelector('h2').textContent)+'</a>';entry.prepend(origin);}}
function render(){let r=getMatches();$('result-count').textContent=`${r.length.toLocaleString()} matching entries · showing ${Math.min(limit,r.length).toLocaleString()}`;$('events').innerHTML=r.length?r.slice(0,limit).map(card).join(''):'<p class="empty">No matching entries. Broaden the filters or switch to the complete register.</p>';$('load-more').hidden=$('show-all').hidden=r.length<=limit;renderContext(r);}
function focusHash(){let m=location.hash.match(/^#event=(.+)$/);if(!m)return;let id=decodeURIComponent(m[1]);if(!events.some(e=>e.id===id))return;$('view').value='all';for(const x of ['layer','kind','year'])$(x).value='';$('search').value=id;limit=40;render();requestAnimationFrame(()=>{const el=$(id);if(el){el.querySelector('details').open=true;el.scrollIntoView({block:'start'});}});}
function renderContracts(){let q=$('contract-search').value.toLowerCase();let rows=contracts.filter(x=>JSON.stringify(x).toLowerCase().includes(q));$('contract-table').innerHTML=`<p class="small">${rows.length} matching contracts</p>`+table(['Contract','Administrator','Code / height','Records'],rows.map(c=>[esc(c.label)+'<br><code>'+esc(c.address)+'</code>','<code>'+esc(c.admin||'No admin')+'</code>',esc(c.code_id)+' / '+esc(c.height),anchor({url:c.original,label:'Original'})+' · '+anchor({url:c.source,label:'Saved'})]));}
function amount(a){if(!a)return '—';return esc(Number(a.amount).toLocaleString('en-US',{maximumFractionDigits:6})+' '+a.asset);}
async function init(){try{let [d,c,f]=await Promise.all(['events.json','sources/contracts.json','sources/funding-register.json'].map(x=>fetch(x).then(r=>{if(!r.ok)throw Error(x);return r.json();})));events=d.events.map(e=>({...e,search:JSON.stringify(e).toLowerCase()}));contracts=c.contracts;options('layer',events.map(e=>e.layer));options('kind',events.map(e=>e.kind));options('year',events.filter(e=>e.date).map(e=>e.date.slice(0,4)));for(const id of ['view','layer','kind','year','search','order'])$(id).addEventListener(id==='search'?'input':'change',()=>{limit=40;render();});$('reset-filters').onclick=()=>{$('view').value='featured';for(const id of ['layer','kind','year','search'])$(id).value='';$('order').value='asc';limit=40;render();};$('load-more').onclick=()=>{limit+=40;render();};$('show-all').onclick=()=>{limit=events.length;render();};$('contract-search').addEventListener('input',renderContracts);$('funding-table').innerHTML=table(['Project / proposal','Approved or requested · historical USD','Actual receipt / reported amount','Status / basis'],f.records.map(x=>{let v=x.valuation||{};let price=v.usd!==undefined?'<strong>'+esc(dollars(v.usd))+'</strong>':'<strong>USD unpriced</strong>';let recv=x.actual_direct_receipt_amount?amount(x.actual_direct_receipt_amount)+'<br><strong>'+esc(dollars(x.receipt_usd))+'</strong> at receipt times<br><span class="small">'+esc((x.receipt_dates||[]).map(d=>d.slice(0,10)).join(', '))+'</span>':x.reported_received_amount?amount(x.reported_received_amount)+' reported by source':x.claimed_state_amount?amount(x.claimed_state_amount)+' claimed-state observation':'No direct receipt established in this sub-register';return [esc(x.project)+'<br>'+x.refs.map(anchor).join(' · '),amount(x.approved_amount||x.request_or_proposed_amount)+'<br>'+price+'<br><span class="small">'+esc(v.basis||'')+' '+esc(v.at_utc?.slice(0,10)||'')+'</span>',recv,esc(({PROPOSAL_STATUS_REJECTED:'Rejected request',PROPOSAL_STATUS_PASSED:'Passed proposal','Executed setup':'Approved and executed'})[x.approval_status]||x.approval_status)+'<br><span class="small">'+esc(x.financial_capacity)+' '+esc(x.coverage_note||'')+' '+esc(x.unpaid_note||'')+'</span>'];}));render();renderContracts();focusHash();window.addEventListener('hashchange',focusHash);}catch(e){$('events').innerHTML='<p class="error">The interactive register could not load. The CSV and JSON downloads below remain available.</p>';}}
init();})();
